<script>
  import { format } from "d3-format";
  import EditableRegressionPlot from "./EditableRegressionPlot.svelte";
  import {
    DEFAULT_PRESENTATION_DATASET_INDEX,
    getPresetDataset,
    PRESET_DATASET_INDICES,
    PRESET_DATASET_COUNT,
  } from "../lib/data.js";
  import { clamp, getMeanBaseline, getPlotDomains, summarizeLoss } from "../lib/model.js";

  const metricFormatter = format(".3f");
  const parameterFormatter = format(".2f");
  const metricLabels = {
    none: "Hidden",
    mae: "Mean Absolute Error",
    mse: "Mean Squared Error",
  };
  const defaultXAxisLabel = "Temperature (C)";
  const defaultYAxisLabel = "Ice Creams Sold";

  let metricMode = "none";
  let datasetIndex = DEFAULT_PRESENTATION_DATASET_INDEX;
  let points = getPresetDataset(datasetIndex);
  let model = getMeanBaseline(points);
  let showControls = true;
  let mode = "fitting";
  let xAxisLabel = defaultXAxisLabel;
  let yAxisLabel = defaultYAxisLabel;
  let xAxisLimitInput = "";
  let yAxisLimitInput = "";
  let predictionX = 5;
  let settingsOpen = false;
  let preservedDomains = null;
  let editablePoints = false;

  $: metricSummary = summarizeLoss(points, model, metricMode === "none" ? "mse" : metricMode);
  $: xAxisLimit = parseAxisLimit(xAxisLimitInput);
  $: yAxisLimit = parseAxisLimit(yAxisLimitInput);
  $: inferredXUpperBound = getInferredUpperBound(points, "x");
  $: predictionMax = xAxisLimit ?? inferredXUpperBound;
  $: predictionX = clamp(predictionX, 0, predictionMax);
  $: predictionY = model.bias + model.weight * predictionX;
  $: activeXMin = preservedDomains?.xDomain?.[0] ?? null;
  $: activeXMax = xAxisLimit ?? preservedDomains?.xDomain?.[1] ?? null;
  $: activeYMin = preservedDomains?.yDomain?.[0] ?? null;
  $: activeYMax = yAxisLimit ?? preservedDomains?.yDomain?.[1] ?? null;

  function parseAxisLimit(value) {
    const numericValue = Number(value);
    return Number.isFinite(numericValue) && numericValue > 0 ? numericValue : null;
  }

  function getInferredUpperBound(nextPoints, field) {
    const maximum = nextPoints.length
      ? Math.max(0, ...nextPoints.map((point) => point[field]))
      : 0;

    return Math.max(Math.ceil((maximum + Math.max(maximum * 0.15, 1)) * 10) / 10, 10);
  }

  function resetModel(nextPoints = points) {
    model = getMeanBaseline(nextPoints);
  }

  function initializePrediction(nextPoints = points) {
    predictionX = getInferredUpperBound(nextPoints, "x") / 2;
  }

  function handlePointsChange(event) {
    points = event.detail.points;
    preservedDomains = null;
    resetModel(points);
    initializePrediction(points);
  }

  function shuffleData() {
    datasetIndex = (datasetIndex + 1) % PRESET_DATASET_COUNT;
    points = getPresetDataset(datasetIndex);
    preservedDomains = null;
    resetModel(points);
    initializePrediction(points);
    mode = "fitting";
  }

  function clearAllPoints() {
    preservedDomains = getPlotDomains(points, model, xAxisLimit, yAxisLimit);
    points = [];
    resetModel(points);
    initializePrediction(points);
  }

  function loadDataset(index) {
    datasetIndex = index;
    points = getPresetDataset(index);
    preservedDomains = null;
    resetModel(points);
    initializePrediction(points);
    mode = "fitting";
  }

  function updateModel(field, value) {
    model = {
      ...model,
      [field]: Number(value),
    };
  }

  function updateModelFromInput(field, event, minValue, maxValue) {
    const numericValue = Number(event.currentTarget.value);

    if (!Number.isFinite(numericValue)) {
      return;
    }

    updateModel(field, clamp(numericValue, minValue, maxValue));
  }

  function enterPredictionMode() {
    initializePrediction(points);
    mode = "prediction";
  }

  function returnToFittingMode() {
    mode = "fitting";
  }
</script>

<section class="demo-shell">
  <div class="section-header">
    <div>
      <h2>Manual Fit</h2>
      <p>
        Move the line until it matches the points. When the line looks good, switch to prediction mode
        and test what your model would guess next.
      </p>
    </div>
    <div class="header-actions">
      <button on:click={mode === "fitting" ? enterPredictionMode : returnToFittingMode}>
        {mode === "fitting" ? "Done Fitting!" : "Continue Fitting"}
      </button>
      <button class="secondary" on:click={() => (showControls = !showControls)}>
        {showControls ? "Hide Controls" : "Show Controls"}
      </button>
    </div>
  </div>

  <div class:collapsed={!showControls} class="demo-grid">
    {#if showControls}
      <aside class="control-panel">
        {#if mode === "fitting"}
          <div class="button-row">
            <button on:click={shuffleData}>New Data</button>
            <button class="secondary" on:click={() => resetModel(points)}>Reset To Avg.</button>
          </div>

          <div class="toggle-row" role="tablist" aria-label="Metric selection">
            <button class:active={metricMode === "none"} on:click={() => (metricMode = "none")}>Hide Error</button>
            <button class:active={metricMode === "mae"} on:click={() => (metricMode = "mae")}>MAE</button>
            <button class:active={metricMode === "mse"} on:click={() => (metricMode = "mse")}>MSE</button>
          </div>

          {#if metricMode !== "none"}
            <div class="stat-card">
              <p class="label">Current Metric</p>
              <strong>{metricLabels[metricMode]}</strong>
              <p class="value">{metricFormatter(metricSummary.mean)}</p>
              <p class="caption">{points.length} points in this tab</p>
            </div>
          {/if}

          <label class="slider-block" for="mse-bias">
            <span>Bias</span>
            <span class="slider-value">
              <!-- <strong>{parameterFormatter(model.bias)}</strong> -->
              <input
                aria-label="Bias value"
                type="number"
                min="-40"
                max="100"
                step="0.2"
                value={model.bias}
                on:change={(event) => updateModelFromInput("bias", event, -40, 100)}
              />
            </span>
          </label>
          <input
            id="mse-bias"
            type="range"
            min="-40"
            max="100"
            step="0.2"
            value={model.bias}
            on:input={(event) => updateModel("bias", event.currentTarget.value)}
          />

          <label class="slider-block" for="mse-weight">
            <span>Weight</span>
            <span class="slider-value">
              <!-- <strong>{parameterFormatter(model.weight)}</strong> -->
              <input
                aria-label="Weight value"
                type="number"
                min="-6"
                max="8"
                step="0.01"
                value={model.weight}
                on:change={(event) => updateModelFromInput("weight", event, -6, 8)}
              />
            </span>
          </label>
          <input
            id="mse-weight"
            type="range"
            min="-6"
            max="8"
            step="0.01"
            value={model.weight}
            on:input={(event) => updateModel("weight", event.currentTarget.value)}
          />
        {:else}
          <div class="prediction-card">
            <p class="label">Prediction Time</p>
            <p class="caption">Your line is locked in. Slide the x-value and watch the model make a guess.</p>
          </div>

          <label class="slider-block" for="mse-prediction-x">
            <span>Choose an x-value</span>
            <strong>{parameterFormatter(predictionX)}</strong>
          </label>
          <input
            id="mse-prediction-x"
            type="range"
            min="0"
            max={predictionMax}
            step="1"
            bind:value={predictionX}
          />

          <div class="stat-card">
            <p class="label">Model's Guess</p>
            <p class="value">{metricFormatter(predictionY)}</p>
            <p class="caption">When x = {parameterFormatter(predictionX)}</p>
          </div>
        {/if}

        <div class="equation-block">
          <p class="label">Current Model</p>
          <strong>y = {parameterFormatter(model.weight)}x + {parameterFormatter(model.bias)}</strong>
        </div>

        {#if mode === "fitting"}
          <details class="settings-panel" bind:open={settingsOpen}>
            <summary>Additional Setting</summary>
            <div class="settings-body">
              <div class="button-row settings-buttons">
                <button class="secondary" on:click={clearAllPoints}>Clear Data</button>
                <button class="secondary" on:click={() => (editablePoints = !editablePoints)}>
                  {editablePoints ? "Disable Editing" : "Enable Editing"}
                </button>
              </div>

              <div class="dataset-picker" role="group" aria-label="Choose a dataset">
                {#each PRESET_DATASET_INDICES as presetIndex}
                  <button
                    class="secondary"
                    class:is-selected={datasetIndex === presetIndex}
                    on:click={() => loadDataset(presetIndex)}
                  >
                    Dataset {presetIndex + 1}
                  </button>
                {/each}
              </div>

              <div class="axis-grid">
                <label class="text-block" for="mse-x-label">
                  <span>X-Axis Label</span>
                  <input id="mse-x-label" type="text" bind:value={xAxisLabel} />
                </label>
                <label class="text-block" for="mse-y-label">
                  <span>Y-Axis Label</span>
                  <input id="mse-y-label" type="text" bind:value={yAxisLabel} />
                </label>
              </div>

              <div class="limits-row">
                <label class="text-block compact" for="mse-x-max">
                  <span>X Max</span>
                  <input id="mse-x-max" type="number" min="0" step="0.1" bind:value={xAxisLimitInput} />
                </label>
                <label class="text-block compact" for="mse-y-max">
                  <span>Y Max</span>
                  <input id="mse-y-max" type="number" min="0" step="0.1" bind:value={yAxisLimitInput} />
                </label>
              </div>
            </div>
          </details>
        {/if}
      </aside>
    {/if}

    <div class="plot-panel">
      <EditableRegressionPlot
        points={points}
        model={model}
        residualStyle={metricMode === "none" ? "none" : metricMode === "mse" ? "square" : "line"}
        xLabel={xAxisLabel || defaultXAxisLabel}
        yLabel={yAxisLabel || defaultYAxisLabel}
        xMin={activeXMin}
        xMax={activeXMax}
        yMin={activeYMin}
        yMax={activeYMax}
        editable={editablePoints}
        showPrediction={mode === "prediction"}
        {predictionX}
        on:pointschange={handlePointsChange}
      />
    </div>
  </div>
</section>

<style>
  .demo-shell {
    display: grid;
    gap: 1.5rem;
  }

  .section-header {
    display: flex;
    align-items: start;
    justify-content: space-between;
    gap: 1rem;
  }

  .header-actions {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
    justify-content: end;
  }

  .section-header h2 {
    margin: 0 0 0.5rem;
  }

  .section-header p {
    margin: 0;
    max-width: 48rem;
    line-height: 1.6;
  }

  .demo-grid {
    display: grid;
    grid-template-columns: minmax(280px, 340px) minmax(0, 1fr);
    gap: 1.25rem;
    align-items: start;
  }

  .demo-grid.collapsed {
    grid-template-columns: 1fr;
  }

  .control-panel,
  .plot-panel {
    border: 1px solid rgba(22, 32, 42, 0.12);
    border-radius: 20px;
    background: rgba(255, 255, 255, 0.88);
    box-shadow: 0 10px 30px rgba(22, 32, 42, 0.06);
  }

  .control-panel {
    display: grid;
    gap: 1rem;
    padding: 1rem;
  }

  .plot-panel {
    padding: 1rem;
  }

  .button-row,
  .toggle-row,
  .dataset-picker {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
  }

  button {
    border: 0;
    border-radius: 999px;
    padding: 0.75rem 1rem;
    font: inherit;
    font-weight: 600;
    background: #1b8cff;
    color: #fff;
    cursor: pointer;
  }

  button.secondary {
    background: rgba(22, 32, 42, 0.08);
    color: #16202a;
  }

  button.is-selected {
    background: #35664d;
    color: #fff;
  }

  .toggle-row button {
    background: rgba(22, 32, 42, 0.08);
    color: #16202a;
  }

  .toggle-row button.active {
    background: #35664d;
    color: #fff;
  }

  .stat-card,
  .equation-block {
    border-radius: 16px;
    background: rgba(27, 140, 255, 0.08);
    padding: 0.95rem 1rem;
  }

  .label,
  .caption {
    margin: 0;
    font-size: 0.85rem;
    color: rgba(22, 32, 42, 0.68);
  }

  .value {
    margin: 0.25rem 0;
    font-size: 1.8rem;
    font-weight: 700;
  }

  .slider-block {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-weight: 600;
  }

  .slider-value {
    display: flex;
    align-items: center;
    gap: 0.65rem;
  }

  .slider-value input {
    width: 6rem;
    border: 1px solid rgba(22, 32, 42, 0.16);
    border-radius: 12px;
    padding: 0.45rem 0.7rem;
    font: inherit;
    font-weight: 600;
    line-height: 1.2;
    color: #16202a;
    background: rgba(255, 255, 255, 0.95);
    text-align: right;
    appearance: textfield;
    -moz-appearance: textfield;
  }

  .slider-value input::-webkit-outer-spin-button,
  .slider-value input::-webkit-inner-spin-button {
    -webkit-appearance: none;
    margin: 0;
  }

  .text-block {
    display: grid;
    gap: 0.4rem;
    font-weight: 600;
    min-width: 0;
  }

  .text-block.compact input {
    max-width: 100%;
  }

  .text-block input {
    box-sizing: border-box;
    width: 100%;
    border: 1px solid rgba(22, 32, 42, 0.16);
    border-radius: 12px;
    padding: 0.55rem 0.75rem;
    font: inherit;
  }

  .settings-panel {
    border: 1px solid rgba(22, 32, 42, 0.1);
    border-radius: 16px;
    background: rgba(22, 32, 42, 0.03);
    padding: 0.2rem 0.85rem 0.85rem;
  }

  .settings-panel summary {
    cursor: pointer;
    font-weight: 700;
    padding: 0.65rem 0 0.4rem;
  }

  .settings-body {
    display: grid;
    gap: 0.85rem;
    padding-top: 0.35rem;
  }

  .settings-buttons {
    justify-content: start;
  }

  .axis-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 0.75rem;
  }

  .limits-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem;
  }

  .prediction-card {
    border-radius: 16px;
    background: rgba(53, 102, 77, 0.08);
    padding: 0.95rem 1rem;
  }

  input[type="range"] {
    width: 100%;
  }

  @media (max-width: 900px) {
    .section-header,
    .demo-grid {
      grid-template-columns: 1fr;
    }
  }
</style>