<script>
  import { format } from "d3-format";
  import EditableRegressionPlot from "./EditableRegressionPlot.svelte";
  import {
    DEFAULT_PRESENTATION_DATASET_INDEX,
    getPresetDataset,
    PRESET_DATASET_COUNT,
    PRESET_DATASET_INDICES,
  } from "../lib/data.js";
  import { clamp, getMeanBaseline, getPlotDomains, roundValue } from "../lib/model.js";

  const parameterFormatter = format(".2f");
  const defaultXAxisLabel = "Temperature (C)";
  const defaultYAxisLabel = "Ice Creams Sold";

  let datasetIndex = DEFAULT_PRESENTATION_DATASET_INDEX;
  let points = getPresetDataset(datasetIndex);
  let xAxisLabel = defaultXAxisLabel;
  let yAxisLabel = defaultYAxisLabel;
  let xAxisLimitInput = "";
  let yAxisLimitInput = "";
  let guessX = Math.round(getInferredUpperBound(points, "x") / 2);
  let guessPoint = null;
  let settingsOpen = false;
  let preservedDomains = null;
  let showControls = false;

  $: xAxisLimit = parseAxisLimit(xAxisLimitInput);
  $: yAxisLimit = parseAxisLimit(yAxisLimitInput);
  $: inferredXUpperBound = getInferredUpperBound(points, "x");
  $: guessMax = xAxisLimit ?? inferredXUpperBound;
  $: guessX = clamp(guessX, 0, guessMax);
  $: activeXMin = preservedDomains?.xDomain?.[0] ?? null;
  $: activeXMax = xAxisLimit ?? preservedDomains?.xDomain?.[1] ?? null;
  $: activeYMin = preservedDomains?.yDomain?.[0] ?? null;
  $: activeYMax = yAxisLimit ?? preservedDomains?.yDomain?.[1] ?? null;
  $: if (guessPoint && roundValue(guessPoint.x, 2) !== roundValue(guessX, 2)) {
    guessPoint = null;
  }

  function parseAxisLimit(value) {
    const numericValue = Number(value);
    return Number.isFinite(numericValue) && numericValue > 0 ? numericValue : null;
  }

  function getInferredUpperBound(nextPoints, field) {
    const maximum = nextPoints.length
      ? Math.max(0, ...nextPoints.map((point) => point[field]))
      : 0;

    return Math.max(Math.ceil((maximum + Math.max(maximum * 0.15, 1)) * 10) / 10, 30);
  }

  function initializeGuess(nextPoints = points) {
    guessX = Math.round(getInferredUpperBound(nextPoints, "x") / 2);
    guessPoint = null;
  }

  function setGuessX(value) {
    guessX = Number(value);
    guessPoint = null;
  }

  function loadDataset(index) {
    datasetIndex = index;
    points = getPresetDataset(index);
    preservedDomains = null;
    initializeGuess(points);
  }

  function newData() {
    loadDataset((datasetIndex + 1) % PRESET_DATASET_COUNT);
  }

  function clearAllPoints() {
    preservedDomains = getPlotDomains(points, getMeanBaseline(points), xAxisLimit, yAxisLimit, false);
    points = [];
    guessPoint = null;
    initializeGuess(points);
  }

  function handleGuessChange(event) {
    guessPoint = event.detail.point;
  }
</script>

<section class="demo-shell">
  <div class="section-header">
    <div>
      <h2>Human Guess</h2>
      <p>
        Study the scatterplot first, then make your own prediction. Pick an x-value,
        find the dotted guide, and click on that line to submit what you think the matching y-value should be.
      </p>
    </div>
    <div class="header-actions">
      <button class="secondary" on:click={() => (showControls = !showControls)}>
        {showControls ? "Hide Controls" : "Show Controls"}
      </button>
    </div>
  </div>

  <div class:collapsed={!showControls} class="demo-grid">
    {#if showControls}
      <aside class="control-panel">
        <div class="button-row">
          <button on:click={newData}>New Data</button>
        </div>

        <label class="slider-block" for="human-guess-x">
          <span>{xAxisLabel || defaultXAxisLabel}</span>
          <strong>{parameterFormatter(guessX)}</strong>
        </label>
        <input
          id="human-guess-x"
          type="range"
          min="0"
          max={guessMax}
          step="1"
          value={guessX}
          on:input={(event) => setGuessX(event.currentTarget.value)}
        />

        <details class="settings-panel" bind:open={settingsOpen}>
          <summary>Additional Setting</summary>
          <div class="settings-body">
            <div class="button-row settings-buttons">
              <button class="secondary" on:click={clearAllPoints}>Clear Data</button>
            </div>

            <div class="dataset-picker" role="group" aria-label="Choose a dataset">
              {#each PRESET_DATASET_INDICES as presetIndex}
                <button
                  class="secondary"
                  class:is-selected={datasetIndex === presetIndex}
                  on:click={() => loadDataset(presetIndex)}
                >
                  Dataset {presetIndex + 1}
                </button>
              {/each}
            </div>

            <div class="axis-grid">
              <label class="text-block" for="human-x-label">
                <span>X-Axis Label</span>
                <input id="human-x-label" type="text" bind:value={xAxisLabel} />
              </label>
              <label class="text-block" for="human-y-label">
                <span>Y-Axis Label</span>
                <input id="human-y-label" type="text" bind:value={yAxisLabel} />
              </label>
            </div>

            <div class="limits-row">
              <label class="text-block compact" for="human-x-max">
                <span>X Max</span>
                <input id="human-x-max" type="number" min="0" step="0.1" bind:value={xAxisLimitInput} />
              </label>
              <label class="text-block compact" for="human-y-max">
                <span>Y Max</span>
                <input id="human-y-max" type="number" min="0" step="0.1" bind:value={yAxisLimitInput} />
              </label>
            </div>
          </div>
        </details>
      </aside>
    {/if}

    <div class="visual-panel">
      <div class="prompt-card">
        <p class="prompt-kicker">Your turn</p>
        <h3>What do you think {yAxisLabel || defaultYAxisLabel} would be when {xAxisLabel || defaultXAxisLabel} is {parameterFormatter(guessX)}?</h3>
        <p>Click on the dotted line to lock in your answer.</p>
      </div>

      <div class="plot-card">
        <EditableRegressionPlot
          points={points}
          model={{ weight: 0, bias: 0 }}
          residualStyle="none"
          xLabel={xAxisLabel || defaultXAxisLabel}
          yLabel={yAxisLabel || defaultYAxisLabel}
          xMin={activeXMin}
          xMax={activeXMax}
          yMin={activeYMin}
          yMax={activeYMax}
          editable={false}
          showRegressionLine={false}
          guideX={guessX}
          guideLabel={`x = ${parameterFormatter(guessX)}`}
          {guessPoint}
          allowGuessPlacement={true}
          on:guesschange={handleGuessChange}
        />
      </div>
    </div>
  </div>
</section>

<style>
  .demo-shell {
    display: grid;
    gap: 1.5rem;
  }

  .section-header {
    display: flex;
    align-items: start;
    justify-content: space-between;
    gap: 1rem;
  }

  .section-header h2 {
    margin: 0 0 0.5rem;
  }

  .section-header p {
    margin: 0;
    max-width: 50rem;
    line-height: 1.6;
  }

  .header-actions {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
    justify-content: end;
  }

  .demo-grid {
    display: grid;
    grid-template-columns: minmax(300px, 360px) minmax(0, 1fr);
    gap: 1.25rem;
    align-items: start;
  }

  .demo-grid.collapsed {
    grid-template-columns: 1fr;
  }

  .control-panel,
  .plot-card,
  .prompt-card {
    border: 1px solid rgba(22, 32, 42, 0.12);
    border-radius: 20px;
    background: rgba(255, 255, 255, 0.88);
    box-shadow: 0 10px 30px rgba(22, 32, 42, 0.06);
  }

  .control-panel {
    display: grid;
    gap: 1rem;
    padding: 1rem;
  }

  .visual-panel {
    display: grid;
    gap: 1rem;
  }

  .prompt-card,
  .plot-card {
    padding: 1rem;
  }

  .prompt-card {
    text-align: center;
    background:
      linear-gradient(135deg, rgba(255, 209, 102, 0.22), rgba(27, 140, 255, 0.12)),
      rgba(255, 255, 255, 0.95);
  }

  .prompt-kicker {
    margin: 0 0 0.4rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    font-size: 0.78rem;
    color: #35664d;
    font-weight: 700;
  }

  .prompt-card h3 {
    margin: 0;
    font-size: clamp(1.5rem, 2.6vw, 2.3rem);
    line-height: 1.2;
  }

  .prompt-card p {
    margin: 0.6rem 0 0;
    color: rgba(22, 32, 42, 0.72);
  }

  .button-row,
  .dataset-picker {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
  }

  button {
    border: 0;
    border-radius: 999px;
    padding: 0.75rem 1rem;
    font: inherit;
    font-weight: 600;
    background: #1b8cff;
    color: #fff;
    cursor: pointer;
  }

  button.secondary {
    background: rgba(22, 32, 42, 0.08);
    color: #16202a;
  }

  button.is-selected {
    background: #35664d;
    color: #fff;
  }

  .slider-block {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-weight: 600;
  }

  .text-block {
    display: grid;
    gap: 0.4rem;
    font-weight: 600;
    min-width: 0;
  }

  .text-block input {
    box-sizing: border-box;
    width: 100%;
    border: 1px solid rgba(22, 32, 42, 0.16);
    border-radius: 12px;
    padding: 0.55rem 0.75rem;
    font: inherit;
  }

  .text-block.compact input {
    max-width: 100%;
  }

  .settings-panel {
    border: 1px solid rgba(22, 32, 42, 0.1);
    border-radius: 16px;
    background: rgba(22, 32, 42, 0.03);
    padding: 0.2rem 0.85rem 0.85rem;
  }

  .settings-panel summary {
    cursor: pointer;
    font-weight: 700;
    padding: 0.65rem 0 0.4rem;
  }

  .settings-body {
    display: grid;
    gap: 0.85rem;
    padding-top: 0.35rem;
  }

  .settings-buttons {
    justify-content: start;
  }

  .axis-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 0.75rem;
  }

  .limits-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem;
  }

  input[type="range"] {
    width: 100%;
  }

  @media (max-width: 960px) {
    .demo-grid {
      grid-template-columns: 1fr;
    }
  }
</style>