<script>
  import { max } from "d3-array";
  import { format } from "d3-format";
  import { scaleLinear } from "d3-scale";
  import { line } from "d3-shape";

  export let history = [];

  const tickFormatter = format(".3~g");
  const width = 680;
  const height = 240;
  const margin = {
    top: 20,
    right: 24,
    bottom: 48,
    left: 68,
  };

  $: safeHistory = history.length ? history : [{ iteration: 0, error: 0 }];
  $: maxIteration = Math.max(max(safeHistory, (point) => point.iteration), 1);
  $: maxError = Math.max(max(safeHistory, (point) => point.error), 1);

  $: xScale = scaleLinear()
    .domain([0, maxIteration])
    .range([margin.left, width - margin.right]);

  $: yScale = scaleLinear()
    .domain([0, maxError * 1.15])
    .range([height - margin.bottom, margin.top]);

  $: errorPath = line()
    .x((point) => xScale(point.iteration))
    .y((point) => yScale(point.error))(safeHistory);

  $: latestPoint = safeHistory[safeHistory.length - 1];
</script>

<div class="history-shell">
  <svg viewBox={`0 0 ${width} ${height}`} aria-label="Gradient descent error history">
    {#each xScale.ticks(6) as tick}
      <g transform={`translate(${xScale(tick)} ${height - margin.bottom})`}>
        <line
          class="grid-line"
          x1="0"
          x2="0"
          y1="0"
          y2={-(height - margin.top - margin.bottom)}
        />
        <text class="axis-text" y="18" text-anchor="middle">{tick}</text>
      </g>
    {/each}

    {#each yScale.ticks(5) as tick}
      <g transform={`translate(${margin.left} ${yScale(tick)})`}>
        <line
          class="grid-line"
          x1="0"
          x2={width - margin.left - margin.right}
          y1="0"
          y2="0"
        />
        <text class="axis-text" x="-10" text-anchor="end" dominant-baseline="middle">
          {tickFormatter(tick)}
        </text>
      </g>
    {/each}

    <line
      class="axis-line"
      x1={margin.left}
      x2={width - margin.right}
      y1={height - margin.bottom}
      y2={height - margin.bottom}
    />
    <line
      class="axis-line"
      x1={margin.left}
      x2={margin.left}
      y1={margin.top}
      y2={height - margin.bottom}
    />

    <text class="axis-label" x={(width + margin.left - margin.right) / 2} y={height - 10}>
      Iterations
    </text>
    <text
      class="axis-label"
      x={-(height / 2)}
      y="18"
      transform="rotate(-90)"
      text-anchor="middle"
    >
      Error (MSE)
    </text>

    <path class="error-line" d={errorPath} />

    <circle class="error-point" cx={xScale(latestPoint.iteration)} cy={yScale(latestPoint.error)} r="5" />
    <text class="error-label" x={xScale(latestPoint.iteration) + 10} y={yScale(latestPoint.error) - 10}>
      {tickFormatter(latestPoint.error)}
    </text>
  </svg>
</div>

<style>
  .history-shell {
    width: 100%;
    min-height: 220px;
  }

  svg {
    display: block;
    width: 100%;
    height: auto;
    overflow: visible;
  }

  .grid-line {
    stroke: rgba(22, 32, 42, 0.1);
    stroke-dasharray: 4 6;
    pointer-events: none;
  }

  .axis-line {
    stroke: rgba(22, 32, 42, 0.6);
    pointer-events: none;
  }

  .axis-label {
    fill: rgba(22, 32, 42, 0.9);
    font-size: 0.9rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }

  .axis-text {
    fill: rgba(22, 32, 42, 0.7);
    font-size: 0.8rem;
  }

  .error-line {
    fill: none;
    stroke: #35664d;
    stroke-width: 3;
  }

  .error-point {
    fill: #f45b69;
    stroke: #16202a;
    stroke-width: 1.5;
  }

  .error-label {
    fill: #16202a;
    font-size: 0.8rem;
    font-weight: 700;
  }
</style>