export function clamp(value, minValue, maxValue) {
  return Math.max(minValue, Math.min(maxValue, value));
}

export function roundValue(value, precision = 2) {
  return Number(value.toFixed(precision));
}

export function predict(model, xValue) {
  return model.bias + model.weight * xValue;
}

export function getMeanBaseline(points) {
  if (!points.length) {
    return { weight: 0, bias: 0 };
  }

  const meanY =
    points.reduce((sum, point) => sum + point.y, 0) / Math.max(points.length, 1);

  return {
    weight: 0,
    bias: roundValue(meanY, 3),
  };
}

export function summarizeLoss(points, model, metric = "mse") {
  const residuals = points.map((point, index) => {
    const prediction = predict(model, point.x);
    const error = point.y - prediction;
    const absoluteError = Math.abs(error);
    const squaredError = error ** 2;

    return {
      ...point,
      index,
      prediction,
      error,
      absoluteError,
      squaredError,
    };
  });

  const total = residuals.reduce((sum, residual) => {
    return sum + (metric === "mae" ? residual.absoluteError : residual.squaredError);
  }, 0);

  return {
    residuals,
    total,
    mean: residuals.length ? total / residuals.length : 0,
  };
}

export function runGradientDescentSteps({
  points,
  model,
  learningRate,
  steps,
  startingIteration,
}) {
  const count = Math.max(points.length, 1);
  let nextModel = { ...model };
  let iteration = startingIteration;
  const history = [];

  for (let step = 0; step < steps; step += 1) {
    let weightSum = 0;
    let biasSum = 0;

    for (const point of points) {
      const prediction = predict(nextModel, point.x);
      const error = point.y - prediction;

      weightSum += point.x * error;
      biasSum += error;
    }

    const weightGradient = (-2 / count) * weightSum;
    const biasGradient = (-2 / count) * biasSum;

    nextModel = {
      weight: nextModel.weight - learningRate * weightGradient,
      bias: nextModel.bias - learningRate * 100 * biasGradient,
    };

    iteration += 1;
    history.push({
      iteration,
      error: summarizeLoss(points, nextModel, "mse").mean,
    });
  }

  return {
    model: {
      weight: roundValue(nextModel.weight, 4),
      bias: roundValue(nextModel.bias, 4),
    },
    iteration,
    history,
  };
}

export function getPlotDomains(points, model, xMax = null, yMax = null, showRegressionLine = true) {
  const safePoints = points.length ? points : [{ x: 0, y: 0 }];
  const xValues = safePoints.map((point) => point.x);
  const xMin = Math.min(...xValues);
  const dataXMax = Math.max(...xValues);
  const xSpan = Math.max(dataXMax - xMin, 1);
  const xPad = Math.max(xSpan * 0.2, 1);
  const effectiveXMax = typeof xMax === "number" && xMax > 0 ? xMax : null;
  const effectiveYMax = typeof yMax === "number" && yMax > 0 ? yMax : null;
  const lineStartX = effectiveXMax === null ? xMin - xPad * 0.35 : 0;
  const lineEndX = effectiveXMax === null ? dataXMax + xPad * 0.35 : effectiveXMax;
  const yCandidates = [...safePoints.map((point) => point.y)];

  if (showRegressionLine) {
    yCandidates.push(
      ...safePoints.map((point) => predict(model, point.x)),
      predict(model, lineStartX),
      predict(model, lineEndX)
    );
  }
  const yMin = Math.min(...yCandidates);
  const dataYMax = Math.max(...yCandidates);
  const ySpan = Math.max(dataYMax - yMin, 1);
  const yPad = Math.max(ySpan * 0.2, 1);

  return {
    xDomain: effectiveXMax === null ? [xMin - xPad, dataXMax + xPad] : [0, effectiveXMax],
    yDomain: effectiveYMax === null ? [yMin - yPad, dataYMax + yPad] : [0, effectiveYMax],
  };
}