<script>
  import { createEventDispatcher } from "svelte";
  import { max, min } from "d3-array";
  import { format } from "d3-format";
  import { scaleLinear } from "d3-scale";
  import { line } from "d3-shape";
  import { clamp, predict, roundValue } from "../lib/model.js";

  export let points = [];
  export let model = { weight: 0, bias: 0 };
  export let residualStyle = "none";
  export let xLabel = "x";
  export let yLabel = "y";
  export let editable = true;
  export let xMin = null;
  export let xMax = null;
  export let yMin = null;
  export let yMax = null;
  export let predictionX = null;
  export let showPrediction = false;
  export let showRegressionLine = true;
  export let guideX = null;
  export let guideLabel = "";
  export let guessPoint = null;
  export let allowGuessPlacement = false;

  const dispatch = createEventDispatcher();
  const tickFormatter = format(".2~g");
  const width = 680;
  const height = 420;
  const margin = {
    top: 24,
    right: 24,
    bottom: 54,
    left: 68,
  };

  let svgElement;
  let draggingIndex = null;
  let isDragging = false;
  let activePointerId = null;
  const guessGuideTolerancePx = 14;

  $: safePoints = points.length ? points : [{ x: 0, y: 0 }];
  $: dataXMin = min(safePoints, (point) => point.x);
  $: dataXMax = max(safePoints, (point) => point.x);
  $: xSpan = Math.max(dataXMax - dataXMin, 1);
  $: xPad = Math.max(xSpan * 0.2, 1);
  $: effectiveXMin = typeof xMin === "number" ? xMin : null;
  $: effectiveXMax = typeof xMax === "number" && xMax > 0 ? xMax : null;
  $: effectiveYMin = typeof yMin === "number" ? yMin : null;
  $: effectiveYMax = typeof yMax === "number" && yMax > 0 ? yMax : null;
  $: lineStartX = effectiveXMax === null ? dataXMin - xPad * 0.35 : effectiveXMin ?? 0;
  $: lineEndX = effectiveXMax === null ? dataXMax + xPad * 0.35 : effectiveXMax;
  $: rawYCandidates = [...safePoints.map((point) => point.y)];
  $: modelYCandidates = showRegressionLine || showPrediction
    ? [
        ...safePoints.map((point) => predict(model, point.x)),
        predict(model, lineStartX),
        predict(model, lineEndX),
      ]
    : [];
  $: predictionY = showPrediction && predictionX !== null ? predict(model, predictionX) : null;
  $: guideXValue = guideX === null ? null : clamp(guideX, effectiveXMin ?? -Infinity, effectiveXMax ?? Infinity);
  $: xCandidates = guideXValue === null ? [...safePoints.map((point) => point.x)] : [...safePoints.map((point) => point.x), guideXValue];
  $: yCandidates = guessPoint ? [...rawYCandidates, ...modelYCandidates, guessPoint.y] : [...rawYCandidates, ...modelYCandidates];
  $: dataYMin = min(yCandidates);
  $: dataYMax = max(yCandidates);
  $: ySpan = Math.max(dataYMax - dataYMin, 1);
  $: yPad = Math.max(ySpan * 0.2, 1);

  $: xDomain =
    effectiveXMin !== null && effectiveXMax !== null
      ? [effectiveXMin, effectiveXMax]
      : effectiveXMax === null
        ? [min(xCandidates) - xPad, max(xCandidates) + xPad]
        : [0, effectiveXMax];
  $: yDomain =
    effectiveYMin !== null && effectiveYMax !== null
      ? [effectiveYMin, effectiveYMax]
      : effectiveYMax === null
        ? [dataYMin - yPad, dataYMax + yPad]
        : [0, effectiveYMax];

  $: xScale = scaleLinear()
    .domain(xDomain)
    .range([margin.left, width - margin.right]);

  $: yScale = scaleLinear()
    .domain(yDomain)
    .range([height - margin.bottom, margin.top]);

  $: regressionLine = [
    { x: lineStartX, y: predict(model, lineStartX) },
    { x: lineEndX, y: predict(model, lineEndX) },
  ];

  $: regressionPath = line()
    .x((point) => xScale(point.x))
    .y((point) => yScale(point.y))(regressionLine);

  $: residuals = safePoints.map((point, index) => {
    const prediction = predict(model, point.x);
    const yPoint = yScale(point.y);
    const yPrediction = yScale(prediction);

    return {
      ...point,
      index,
      prediction,
      pixelError: Math.max(Math.abs(yPoint - yPrediction), 1.5),
      pixelX: xScale(point.x),
      pixelY: yPoint,
      predictionPixelY: yPrediction,
    };
  });

  $: predictionPoint =
    showPrediction && predictionX !== null && predictionY !== null
      ? {
          x: clamp(predictionX, xDomain[0], xDomain[1]),
          y: clamp(predictionY, yDomain[0], yDomain[1]),
          rawY: predictionY,
        }
      : null;
  $: predictionLabel = predictionPoint
    ? `x = ${roundValue(predictionPoint.x, 2)}, y = ${roundValue(predictionPoint.rawY, 2)}`
    : "";
  $: predictionLabelWidth = Math.max(predictionLabel.length * 7.4 + 20, 120);
  $: predictionLabelX = predictionPoint ? xScale(predictionPoint.x) : 0;
  $: predictionLabelY = predictionPoint
    ? Math.max(yScale(predictionPoint.y) - 34, margin.top + 6)
    : 0;
  $: guideLabelWidth = Math.max(guideLabel.length * 7.2 + 16, 68);
  $: guideLabelX = guideXPosition ?? 0;
  $: guideLabelY = margin.top + 16;

  $: renderedGuessPoint =
    guessPoint
      ? {
          x: clamp(guessPoint.x, xDomain[0], xDomain[1]),
          y: clamp(guessPoint.y, yDomain[0], yDomain[1]),
          rawY: guessPoint.y,
        }
      : null;

  $: guideXPosition = guideXValue === null ? null : xScale(clamp(guideXValue, xDomain[0], xDomain[1]));

  function emitPoints(nextPoints) {
    dispatch("pointschange", { points: nextPoints });
  }

  function getEventPoint(event) {
    const rect = svgElement.getBoundingClientRect();
    const xPx = ((event.clientX - rect.left) / rect.width) * width;
    const yPx = ((event.clientY - rect.top) / rect.height) * height;

    return {
      xPx,
      yPx,
      x: roundValue(clamp(xScale.invert(xPx), xDomain[0], xDomain[1]), 2),
      y: roundValue(clamp(yScale.invert(yPx), yDomain[0], yDomain[1]), 2),
    };
  }

  function handlePlotPointerUp(event) {
    if (!editable || draggingIndex !== null || isDragging) {
      if (!allowGuessPlacement || guideXPosition === null || draggingIndex !== null || isDragging) {
        return;
      }

      const eventPoint = getEventPoint(event);

      if (Math.abs(eventPoint.xPx - guideXPosition) > guessGuideTolerancePx) {
        return;
      }

      dispatch("guesschange", {
        point: {
          x: roundValue(guideXValue, 2),
          y: eventPoint.y,
        },
      });
      return;
    }

    emitPoints([...points, getEventPoint(event)]);
  }

  function handlePointPointerDown(index, event) {
    if (!editable) {
      return;
    }

    draggingIndex = index;
    isDragging = false;
    activePointerId = event.pointerId;
    if (event.currentTarget.setPointerCapture) {
      event.currentTarget.setPointerCapture(event.pointerId);
    }
    event.stopPropagation();
    event.preventDefault();
  }

  function handlePointerMove(event) {
    if (!editable || draggingIndex === null) {
      return;
    }

    if (activePointerId !== null && event.pointerId !== activePointerId) {
      return;
    }

    isDragging = true;
    const nextPoint = getEventPoint(event);
    emitPoints(
      points.map((point, index) => {
        if (index !== draggingIndex) {
          return point;
        }

        return nextPoint;
      })
    );
  }

  function handleWindowPointerUp(event) {
    if (activePointerId !== null && event.pointerId !== activePointerId) {
      return;
    }

    if (event.currentTarget && event.currentTarget.releasePointerCapture && activePointerId !== null) {
      try {
        event.currentTarget.releasePointerCapture(activePointerId);
      } catch (error) {
        // Ignore release errors when the pointer is no longer captured.
      }
    }

    draggingIndex = null;
    isDragging = false;
    activePointerId = null;
  }

  function handlePointerCancel(event) {
    if (activePointerId !== null && event.pointerId !== activePointerId) {
      return;
    }

    draggingIndex = null;
    isDragging = false;
    activePointerId = null;
  }

  function removePoint(index, event) {
    if (!editable || points.length <= 2) {
      return;
    }

    event.stopPropagation();
    draggingIndex = null;
    isDragging = false;
    emitPoints(points.filter((_, pointIndex) => pointIndex !== index));
  }
</script>

<svelte:window
  on:pointermove={handlePointerMove}
  on:pointerup={handleWindowPointerUp}
  on:pointercancel={handlePointerCancel}
/>

<div class="plot-shell">
  <svg
    bind:this={svgElement}
    viewBox={`0 0 ${width} ${height}`}
    aria-label="Editable regression plot"
    on:pointermove={handlePointerMove}
    on:pointerup={handleWindowPointerUp}
    on:pointercancel={handlePointerCancel}
  >
    <rect
      class="plot-backdrop"
      x={margin.left}
      y={margin.top}
      width={width - margin.left - margin.right}
      height={height - margin.top - margin.bottom}
      on:pointerup={handlePlotPointerUp}
    />

    {#each xScale.ticks(6) as tick}
      <g transform={`translate(${xScale(tick)} ${height - margin.bottom})`}>
        <line
          class="grid-line"
          x1="0"
          x2="0"
          y1="0"
          y2={-(height - margin.top - margin.bottom)}
        />
        <text class="axis-text" y="18" text-anchor="middle">{tickFormatter(tick)}</text>
      </g>
    {/each}

    {#each yScale.ticks(6) as tick}
      <g transform={`translate(${margin.left} ${yScale(tick)})`}>
        <line
          class="grid-line"
          x1="0"
          x2={width - margin.left - margin.right}
          y1="0"
          y2="0"
        />
        <text class="axis-text" x="-10" text-anchor="end" dominant-baseline="middle">
          {tickFormatter(tick)}
        </text>
      </g>
    {/each}

    <line
      class="axis-line"
      x1={margin.left}
      x2={width - margin.right}
      y1={height - margin.bottom}
      y2={height - margin.bottom}
    />
    <line
      class="axis-line"
      x1={margin.left}
      x2={margin.left}
      y1={margin.top}
      y2={height - margin.bottom}
    />

    <text class="axis-label" x={(width + margin.left - margin.right) / 2} y={height - 10}>
      {xLabel}
    </text>
    <text
      class="axis-label"
      x={-(height / 2)}
      y="18"
      transform="rotate(-90)"
      text-anchor="middle"
    >
      {yLabel}
    </text>

    {#if residualStyle === "square"}
      {#each residuals as residual}
        <rect
          class="residual-shape"
          x={residual.y > residual.prediction
            ? residual.pixelX - residual.pixelError
            : residual.pixelX}
          y={Math.min(residual.pixelY, residual.predictionPixelY)}
          width={residual.pixelError}
          height={residual.pixelError}
        />
      {/each}
    {:else if residualStyle === "line"}
      {#each residuals as residual}
        <line
          class="residual-line"
          x1={residual.pixelX}
          x2={residual.pixelX}
          y1={residual.pixelY}
          y2={residual.predictionPixelY}
        />
      {/each}
    {/if}

    {#if guideXPosition !== null}
      <line
        class="guess-guide"
        x1={guideXPosition}
        x2={guideXPosition}
        y1={margin.top}
        y2={height - margin.bottom}
      />
    {/if}

    {#if showRegressionLine}
      <path class="regression-line" d={regressionPath} />
    {/if}

    {#if predictionPoint}
      <circle
        class="prediction-point"
        cx={xScale(predictionPoint.x)}
        cy={yScale(predictionPoint.y)}
        r="7"
      />
      <line
        class="prediction-guide"
        x1={xScale(predictionPoint.x)}
        x2={xScale(predictionPoint.x)}
        y1={yScale(predictionPoint.y)}
        y2={yScale(yDomain[0])}
      />
      <line
        class="prediction-guide"
        x1={xScale(xDomain[0])}
        x2={xScale(predictionPoint.x)}
        y1={yScale(predictionPoint.y)}
        y2={yScale(predictionPoint.y)}
      />
    {/if}

    {#if renderedGuessPoint}
      <polygon
        class="guess-point"
        points={`
          ${xScale(renderedGuessPoint.x)},${yScale(renderedGuessPoint.y) - 9}
          ${xScale(renderedGuessPoint.x) + 9},${yScale(renderedGuessPoint.y)}
          ${xScale(renderedGuessPoint.x)},${yScale(renderedGuessPoint.y) + 9}
          ${xScale(renderedGuessPoint.x) - 9},${yScale(renderedGuessPoint.y)}
        `}
      />
      <text
        class="guess-text"
        x={xScale(renderedGuessPoint.x)}
        y={Math.max(yScale(renderedGuessPoint.y) - 14, margin.top + 30)}
        text-anchor="middle"
      >
        Your guess: {roundValue(renderedGuessPoint.rawY, 2)}
      </text>
    {/if}

    {#each points as point, index}
      <circle
        class="plot-point"
        cx={xScale(point.x)}
        cy={yScale(point.y)}
        r="6"
        on:pointerdown={(event) => handlePointPointerDown(index, event)}
        on:pointermove={handlePointerMove}
        on:pointerup={handleWindowPointerUp}
        on:pointercancel={handlePointerCancel}
        on:dblclick={(event) => removePoint(index, event)}
      />
    {/each}

    {#if guideLabel && guideXPosition !== null}
      <rect
        class="guide-label-backdrop"
        x={guideLabelX - guideLabelWidth / 2}
        y={guideLabelY - 14}
        width={guideLabelWidth}
        height="20"
        rx="7"
      />
      <text class="guide-label" x={guideLabelX} y={guideLabelY} text-anchor="middle" dominant-baseline="middle">
        {guideLabel}
      </text>
    {/if}

    {#if predictionPoint}
      <rect
        class="prediction-label-backdrop"
        x={predictionLabelX - predictionLabelWidth / 2}
        y={predictionLabelY - 16}
        width={predictionLabelWidth}
        height="24"
        rx="8"
      />
      <text
        class="prediction-text"
        x={predictionLabelX}
        y={predictionLabelY}
        text-anchor="middle"
        dominant-baseline="middle"
      >
        {predictionLabel}
      </text>
    {/if}
  </svg>
</div>

<style>
  .plot-shell {
    width: 100%;
    min-height: 280px;
  }

  svg {
    display: block;
    width: 100%;
    height: auto;
    overflow: visible;
  }

  .plot-backdrop {
    fill: rgba(255, 255, 255, 0.72);
    stroke: rgba(22, 32, 42, 0.08);
    rx: 20px;
  }

  .grid-line {
    stroke: rgba(22, 32, 42, 0.1);
    stroke-dasharray: 4 6;
    pointer-events: none;
  }

  .axis-line {
    stroke: rgba(22, 32, 42, 0.6);
    pointer-events: none;
  }

  .axis-text {
    fill: rgba(22, 32, 42, 0.7);
    font-size: 0.8rem;
    pointer-events: none;
  }

  .axis-label {
    fill: rgba(22, 32, 42, 0.9);
    font-size: 0.9rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    pointer-events: none;
  }

  .residual-shape {
    fill: rgba(27, 140, 255, 0.16);
    pointer-events: none;
  }

  .residual-line {
    stroke: rgba(27, 140, 255, 0.7);
    stroke-width: 3;
    pointer-events: none;
  }

  .regression-line {
    fill: none;
    stroke: #12314f;
    stroke-width: 4;
    pointer-events: none;
  }

  .prediction-point {
    fill: #35664d;
    stroke: #16202a;
    stroke-width: 1.5;
    pointer-events: none;
  }

  .prediction-guide {
    stroke: rgba(53, 102, 77, 0.7);
    stroke-width: 2.5;
    stroke-dasharray: 6 5;
    pointer-events: none;
  }

  .guess-guide {
    stroke: rgba(244, 91, 105, 0.85);
    stroke-width: 3;
    stroke-dasharray: 7 6;
    pointer-events: none;
  }

  .guide-label,
  .guess-text {
    fill: #16202a;
    font-size: 0.85rem;
    font-weight: 700;
    pointer-events: none;
  }

  .prediction-label-backdrop {
    fill: rgba(245, 247, 244, 0.96);
    stroke: rgba(22, 32, 42, 0.14);
    stroke-width: 1;
    pointer-events: none;
  }

  .guide-label-backdrop {
    fill: rgba(245, 247, 244, 0.96);
    stroke: rgba(22, 32, 42, 0.12);
    stroke-width: 1;
    pointer-events: none;
  }

  .prediction-text {
    fill: #16202a;
    font-size: 0.85rem;
    font-weight: 700;
    pointer-events: none;
  }

  .plot-point {
    fill: #f45b69;
    stroke: #16202a;
    stroke-width: 1.5;
    cursor: grab;
    touch-action: none;
  }

  .guess-point {
    fill: #ffd166;
    stroke: #16202a;
    stroke-width: 1.5;
    pointer-events: none;
  }

  .plot-point:active {
    cursor: grabbing;
  }
</style>