    display: grid;
    gap: 1rem;
  }

  .plot-card {
    padding: 1rem;
  }

  .button-row,
  .dataset-picker {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
  }

  button {
    border: 0;
    border-radius: 999px;
