    cursor: pointer;
  }

  button.secondary {
    background: rgba(22, 32, 42, 0.08);
    color: #16202a;
  }

  button.is-selected {
    background: #35664d;
    color: #fff;
  }

  .stats-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem;
  }

  .stat-card,
  .equation-block {
    border-radius: 16px;
    background: rgba(53, 102, 77, 0.08);
    padding: 0.95rem 1rem;
  }

  .label {
    margin: 0;
    font-size: 0.85rem;
    color: rgba(22, 32, 42, 0.68);
  }

  .value {
    margin: 0.25rem 0 0;
    font-size: 1.8rem;
    font-weight: 700;
  }

  .slider-block {
    display: flex;
    justify-content: space-between;
    align-items: center;
